<?php

declare(strict_types=1);

function kpi_packing_numeric_quantity(?string $value): ?float
{
    if($value===null||!preg_match('/-?\d+(?:\.\d+)?/',str_replace(',','',(string)$value),$match))return null;return(float)$match[0];
}

function kpi_packing_physical_quantities(?string $value):array
{
    $result=['mass_grams'=>0.0,'volume_ml'=>0.0,'pieces'=>0.0,'parsed'=>false,'packages'=>[]];$text=strtolower(str_replace(',',' ',trim((string)$value)));
    if($text==='')return$result;
    preg_match_all('/(\d+(?:\.\d+)?)\s*(kg|kilograms?|g|grams?|l|litres?|liters?|ml|millilitres?|milliliters?|pcs?|pieces?|units?)\b\s*(?:\(\s*(\d+(?:\.\d+)?)\s*\))?/i',$text,$matches,PREG_SET_ORDER);
    foreach($matches as$match){$amount=(float)$match[1];$unit=strtolower($match[2]);$count=isset($match[3])&&$match[3]!==''?(float)$match[3]:1.0;$total=$amount*$count;$result['parsed']=true;$baseUnit=in_array($unit,['kg','kilogram','kilograms','g','gram','grams'],true)?'g':(in_array($unit,['l','litre','litres','liter','liters','ml','millilitre','millilitres','milliliter','milliliters'],true)?'ml':'pieces');$baseSize=$amount*(in_array($unit,['kg','kilogram','kilograms','l','litre','litres','liter','liters'],true)?1000:1);$packageKey=$baseUnit.':'.(string)$baseSize;$result['packages'][$packageKey]=($result['packages'][$packageKey]??0)+$count;if(in_array($unit,['kg','kilogram','kilograms'],true))$result['mass_grams']+=$total*1000;elseif(in_array($unit,['g','gram','grams'],true))$result['mass_grams']+=$total;elseif(in_array($unit,['l','litre','litres','liter','liters'],true))$result['volume_ml']+=$total*1000;elseif(in_array($unit,['ml','millilitre','millilitres','milliliter','milliliters'],true))$result['volume_ml']+=$total;else$result['pieces']+=$total;}
    ksort($result['packages']);
    return$result;
}

function kpi_packing_package_size(string $value):array
{
    $normalized=strtolower(trim($value));if(!preg_match('/(\d+(?:\.\d+)?)\s*(kg|kilograms?|g|grams?|l|litres?|liters?|ml|millilitres?|milliliters?)\b/i',$normalized,$match))return['type'=>'Unclassified','base_amount'=>null,'unit'=>null,'band'=>'Unclassified'];$amount=(float)$match[1];$unit=strtolower($match[2]);$liquid=in_array($unit,['l','litre','litres','liter','liters','ml','millilitre','millilitres','milliliter','milliliters'],true);if($liquid&&$unit!=='ml'&&strpos($unit,'milli')!==0)$amount*=1000;if(!$liquid&&($unit==='kg'||strpos($unit,'kilo')===0))$amount*=1000;$band=$amount<=100?'Small':($amount<1000?'Medium':'Large');return['type'=>$liquid?'Liquid':'Solid','base_amount'=>$amount,'unit'=>$liquid?'mL':'g','band'=>$band];
}

function kpi_packing_list_performance(array $employee,string $fromSql,string $toSql,array $holidays):array
